package com.anamcara.controller;
import com.anamcara.model.SiteContent;import com.anamcara.repository.SiteContentRepository;import com.anamcara.service.S3MediaService;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.dynamodb.DynamoDbClient;import software.amazon.awssdk.services.dynamodb.model.*;import java.io.IOException;import java.util.*;
@RestController @RequestMapping("/api/content")public class SiteContentUpdateController{private final SiteContentRepository repository;private final S3MediaService media;private final DynamoDbClient db;private final String table;public SiteContentUpdateController(SiteContentRepository repository,S3MediaService media,@org.springframework.beans.factory.annotation.Value("${aws.region}")String region,@org.springframework.beans.factory.annotation.Value("${app.dynamodb.table}")String table){this.repository=repository;this.media=media;this.db=DynamoDbClient.builder().region(Region.of(region)).build();this.table=table;}
@PutMapping(value="/{id}",consumes="multipart/form-data")public SiteContent update(@PathVariable String id,@RequestParam String contentType,@RequestParam(defaultValue="")String title,@RequestParam(defaultValue="")String testimonial,@RequestParam(defaultValue="")String name,@RequestParam(defaultValue="")String company,@RequestParam(required=false)MultipartFile file,@RequestParam(required=false,name="media")MultipartFile legacy)throws IOException{SiteContent item=repository.findAll().stream().filter(c->id.equals(c.id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Content item not found."));if(contentType.equals("TESTIMONIAL")&&(testimonial.isBlank()||name.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Testimonial and name are required.");MultipartFile upload=file!=null?file:legacy;String oldKey=key(item.mediaUrl);if(upload!=null&&!upload.isEmpty())try{var stored=media.store(upload);item.mediaUrl="/api/uploads/"+stored.key();item.mediaType=stored.mediaType();}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}item.contentType=contentType;item.title=title.trim();item.testimonial=testimonial.trim();item.name=name.trim();item.company=company.trim();Map<String,AttributeValue>m=new HashMap<>();m.put("id",s(item.id));m.put("recordType",s("SITE_CONTENT"));m.put("contentType",s(item.contentType));m.put("mediaType",s(item.mediaType));m.put("mediaUrl",s(item.mediaUrl));m.put("title",s(item.title));m.put("testimonial",s(item.testimonial));m.put("name",s(item.name));m.put("company",s(item.company));m.put("createdAt",s(item.createdAt));db.putItem(PutItemRequest.builder().tableName(table).item(m).conditionExpression("recordType=:type").expressionAttributeValues(Map.of(":type",s("SITE_CONTENT"))).build());String newKey=key(item.mediaUrl);if(!oldKey.equals(newKey))media.delete(oldKey);return item;}private String key(String url){return url!=null&&url.startsWith("/api/uploads/")?url.substring(13):(url.startsWith("/uploads/")?url.substring(9):"");}private AttributeValue s(String v){return AttributeValue.builder().s(v==null?"":v).build();}}
